import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    private static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0, length = 0;

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();
        int[][] grid = new int[n][m];

        int mismatches = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = fs.nextInt();
                int expectedParity = (i + j) & 1;
                if ((grid[i][j] & 1) != expectedParity) {
                    mismatches++;
                }
            }
        }

        int total = n * m;
        boolean usePattern = mismatches <= total - mismatches;
        int answer = Math.min(mismatches, total - mismatches);

        StringBuilder out = new StringBuilder();
        out.append(answer).append('\n');

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int expectedParity = (i + j) & 1;
                if (!usePattern) expectedParity ^= 1;
                if ((grid[i][j] & 1) != expectedParity) grid[i][j]++;
                if (j > 0) out.append(' ');
                out.append(grid[i][j]);
            }
            out.append('\n');
        }

        System.out.print(out);
    }
}
